def softmax(Z):
    Z = Z - Z.max(axis=1, keepdims=True)
    E = np.exp(Z)
    return E / E.sum(axis=1, keepdims=True)

def mlp_forward(X, params):
    Z1 = X @ params['W1'] + params['b1']
    H = relu(Z1)
    P = softmax(H @ params['W2'] + params['b2'])
    return P, {'X': X, 'Z1': Z1, 'H': H}

